INSERT INTO pages (id, slug, name, meta_json, status, in_sitemap, sort, created_at, updated_at, published_at) VALUES (1, 'home', 'Homepage', '{"title":{"en":"Home","fr":"Accueil"},"description":{"en":"An independent, modern organisation devoted to the history of the Bavarian Illuminati, Enlightenment philosophy and the pursuit of knowledge.","fr":"Une organisation moderne et indépendante consacrée à l''histoire des Illuminés de Bavière, à la philosophie des Lumières et à la quête du savoir."}}', 'published', 1, 0, 1794301200000, 1794301200000, 1794301200000);
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-0', 'hero', 0, 1, '{}', '{"shared":{"image":"/assets/img/hero-library.jpg","height":"full"},"en":{"eyebrow":"An independent modern society","heading":"Eternal Illuminati Covenant","subheading":"Knowledge. Enlightenment. Legacy.","body":"A community devoted to the history of the Bavarian Illuminati, the ideals of the Enlightenment and the lifelong pursuit of knowledge.","buttons":[{"label":"Apply for membership","href":"/apply","style":"primary"},{"label":"Explore our history","href":"/history","style":"secondary"}]},"fr":{"eyebrow":"Une société moderne et indépendante","heading":"Eternal Illuminati Covenant","subheading":"Savoir. Lumières. Héritage.","body":"Une communauté consacrée à l''histoire des Illuminés de Bavière, aux idéaux des Lumières et à la quête du savoir tout au long de la vie.","buttons":[{"label":"Candidater","href":"/apply","style":"primary"},{"label":"Découvrir notre histoire","href":"/history","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-1', 'text', 1, 1, '{}', '{"shared":{"image":"/assets/img/weishaupt.jpg","imagePosition":"left"},"en":{"eyebrow":"1776 · Ingolstadt","heading":"An Enlightenment society in Bavaria","body":"On **1 May 1776**, Adam Weishaupt, a young professor of canon law at the University of Ingolstadt, founded a small secret society. Its members wanted to spread reason, secular learning and moral self-improvement at a time when Bavarian intellectual life was still closely supervised by Church and state.\n\nWithin a decade the Order of the Illuminati had recruited officials, nobles, scholars and writers across the German-speaking world. Then it was banned, its papers were seized and published, and it disappeared, only to be reborn as a legend.\n\nThe Eternal Illuminati Covenant is a **modern organisation**. We study this history. We do not claim to continue it.","buttons":[{"label":"Read the history","href":"/history","style":"primary"}]},"fr":{"eyebrow":"1776 · Ingolstadt","heading":"Une société des Lumières en Bavière","body":"Le **1er mai 1776**, Adam Weishaupt, jeune professeur de droit canon à l''université d''Ingolstadt, fonde une petite société secrète. Ses membres veulent diffuser la raison, le savoir laïque et le perfectionnement moral, à une époque où la vie intellectuelle bavaroise reste étroitement surveillée par l''Église et l''État.\n\nEn une décennie, l''Ordre des Illuminés recrute fonctionnaires, nobles, savants et écrivains dans tout l''espace germanophone. Puis il est interdit, ses papiers sont saisis et publiés, et il disparaît, pour renaître sous forme de légende.\n\nL''Eternal Illuminati Covenant est une **organisation moderne**. Nous étudions cette histoire ; nous ne prétendons pas la prolonger.","buttons":[{"label":"Lire l''histoire","href":"/history","style":"primary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-2', 'timeline_preview', 2, 1, '{"background":"charcoal"}', '{"shared":{"count":5},"en":{"eyebrow":"Chronology","heading":"From Ingolstadt to legend","intro":"Key dates in the short, documented life of the Bavarian Illuminati, and in the long afterlife of the myth.","buttons":[{"label":"View the full timeline","href":"/timeline","style":"secondary"}]},"fr":{"eyebrow":"Chronologie","heading":"D''Ingolstadt à la légende","intro":"Les dates clés de la brève existence documentée des Illuminés de Bavière, et de la longue postérité du mythe.","buttons":[{"label":"Voir toute la chronologie","href":"/timeline","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-3', 'text', 3, 1, '{}', '{"shared":{"image":"/assets/img/orrery.jpg","imagePosition":"right"},"en":{"eyebrow":"Philosophy","heading":"Sapere aude: dare to know","body":"In 1784 Immanuel Kant described Enlightenment as humanity''s emergence from a self-imposed immaturity, the inability to use one''s own understanding without another''s guidance. His motto, borrowed from Horace, was *sapere aude*: have the courage to use your own reason.\n\nThat spirit of critical inquiry, open discussion and education guides our work today: reading sources carefully, questioning comfortable myths and improving ourselves through study.","buttons":[{"label":"Our philosophy","href":"/philosophy","style":"primary"}]},"fr":{"eyebrow":"Philosophie","heading":"Sapere aude : ose savoir","body":"En 1784, Emmanuel Kant décrit les Lumières comme la sortie de l''humanité d''une minorité dont elle est elle-même responsable : l''incapacité de se servir de son entendement sans la direction d''autrui. Sa devise, empruntée à Horace : *sapere aude*, aie le courage de te servir de ta propre raison.\n\nCet esprit d''examen critique, de libre discussion et d''éducation guide notre travail : lire les sources avec soin, interroger les mythes confortables et se perfectionner par l''étude.","buttons":[{"label":"Notre philosophie","href":"/philosophy","style":"primary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-4', 'principles_list', 4, 1, '{}', '{"shared":{"count":6},"en":{"eyebrow":"Our principles","heading":"Six commitments","intro":"Principles adopted by the modern Covenant to guide its members and its work.","buttons":[{"label":"Read the principles","href":"/principles","style":"secondary"}]},"fr":{"eyebrow":"Nos principes","heading":"Six engagements","intro":"Principes adoptés par le Covenant moderne pour guider ses membres et ses travaux.","buttons":[{"label":"Lire les principes","href":"/principles","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-5', 'symbols_list', 5, 1, '{"background":"charcoal"}', '{"shared":{"count":2},"en":{"eyebrow":"Symbols","heading":"Symbols and their interpretations","intro":"Where historical symbols really come from, and how later myths attached themselves to them.","buttons":[{"label":"All symbols","href":"/symbols","style":"secondary"}]},"fr":{"eyebrow":"Symboles","heading":"Symboles et interprétations","intro":"D''où viennent réellement les symboles historiques, et comment les mythes s''y sont attachés.","buttons":[{"label":"Tous les symboles","href":"/symbols","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-6', 'text', 6, 1, '{}', '{"shared":{"image":"/assets/img/pantheon.jpg","imagePosition":"left"},"en":{"eyebrow":"The Covenant","heading":"A modern society with a historical interest","body":"The Eternal Illuminati Covenant is an independent organisation for people who take history, philosophy and self-improvement seriously. Members study the Enlightenment and the Bavarian Illuminati, discuss sources and ideas, and support one another''s learning.\n\nWe are open about what we are and what we are not. We are not the historical order. We hold no secret power, and we promise no wealth, influence or protection.","buttons":[{"label":"About the Covenant","href":"/covenant","style":"primary"}]},"fr":{"eyebrow":"Le Covenant","heading":"Une société moderne passionnée d’histoire","body":"L''Eternal Illuminati Covenant est une organisation indépendante pour celles et ceux qui prennent au sérieux l''histoire, la philosophie et le perfectionnement personnel. Ses membres étudient les Lumières et les Illuminés de Bavière, discutent des sources et des idées, et s''entraident dans leurs apprentissages.\n\nNous sommes transparents sur ce que nous sommes et ce que nous ne sommes pas : nous ne sommes pas l''ordre historique, nous ne détenons aucun pouvoir secret, et nous ne promettons ni richesse, ni influence, ni protection.","buttons":[{"label":"À propos du Covenant","href":"/covenant","style":"primary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-7', 'articles_list', 7, 1, '{}', '{"shared":{"count":3,"mode":"articles"},"en":{"eyebrow":"Publications","heading":"From the research desk","buttons":[{"label":"All publications","href":"/publications","style":"secondary"}]},"fr":{"eyebrow":"Publications","heading":"Nos dernières publications","buttons":[{"label":"Toutes les publications","href":"/publications","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-8', 'cta', 8, 1, '{"background":"image","bgImage":"/assets/img/admont-library.jpg","overlay":"strong","spacing":"spacious","align":"center"}', '{"shared":{},"en":{"eyebrow":"Membership","heading":"An invitation to apply","body":"Membership is open to adults who share a serious interest in history, philosophy and personal development. Every application is read by a person. We offer study, discussion and fellowship. We do not offer wealth, power or influence.","buttons":[{"label":"Apply for membership","href":"/apply","style":"primary"},{"label":"Membership information","href":"/membership","style":"secondary"}]},"fr":{"eyebrow":"Adhésion","heading":"Une invitation à candidater","body":"L''adhésion est ouverte aux adultes qui partagent un intérêt sérieux pour l''histoire, la philosophie et le développement personnel. Chaque candidature est lue par une personne. Nous offrons l''étude, la discussion et la fraternité ; pas la richesse, le pouvoir ou l''influence.","buttons":[{"label":"Candidater","href":"/apply","style":"primary"},{"label":"Informations sur l''adhésion","href":"/membership","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-9', 'faq_list', 9, 1, '{}', '{"shared":{"count":4},"en":{"eyebrow":"Questions","heading":"Frequently asked","buttons":[{"label":"All questions","href":"/faq","style":"secondary"}]},"fr":{"eyebrow":"Questions","heading":"Questions fréquentes","buttons":[{"label":"Toutes les questions","href":"/faq","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (1, 'seed-home-10', 'cta', 10, 1, '{"background":"charcoal","align":"center"}', '{"shared":{},"en":{"eyebrow":"Contact","heading":"Write to us","body":"Questions about our work, the archive or membership? We read every message.","buttons":[{"label":"Contact us","href":"/contact","style":"secondary"}]},"fr":{"eyebrow":"Contact","heading":"Écrivez-nous","body":"Des questions sur nos travaux, les archives ou l''adhésion ? Nous lisons chaque message.","buttons":[{"label":"Nous contacter","href":"/contact","style":"secondary"}]}}');
INSERT INTO pages (id, slug, name, meta_json, status, in_sitemap, sort, created_at, updated_at, published_at) VALUES (2, 'history', 'Our History', '{"title":{"en":"Our History: The Bavarian Illuminati","fr":"Notre histoire : les Illuminés de Bavière"},"description":{"en":"The documented history of the Bavarian Illuminati (1776–c.1787): origins, founding, Adam Weishaupt, structure, expansion, suppression, and the myths that followed."}}', 'published', 1, 10, 1794301200000, 1794301200000, 1794301200000);
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-0', 'hero', 0, 1, '{}', '{"shared":{"image":"/assets/img/ingolstadt.jpg","height":"medium"},"en":{"eyebrow":"Our history","heading":"The Bavarian Illuminati, 1776–1787","body":"What is documented, what is disputed, and what was invented later."},"fr":{"eyebrow":"Notre histoire","heading":"Les Illuminés de Bavière, 1776–1787","body":"Ce qui est documenté, ce qui est contesté, et ce qui a été inventé plus tard."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-1', 'notice', 1, 1, '{"spacing":"compact"}', '{"shared":{"tone":"info"},"en":{"heading":"History, not lineage","body":"The Eternal Illuminati Covenant is a modern organisation. The Bavarian Illuminati were suppressed in the 1780s, and **no documented organisational continuity** links them to any group today, including ours. On this page we separate established facts from interpretation and from later claims, and we cite our sources."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-2', 'text', 2, 1, '{}', '{"shared":{},"en":{"eyebrow":"Origins","heading":"Bavaria in the 1770s","body":"Electoral Bavaria was a Catholic state in which censorship was strict and education had long been dominated by the Society of Jesus. When Pope Clement XIV suppressed the Jesuits in **1773**, chairs at the University of Ingolstadt fell vacant. Among those appointed was **Adam Weishaupt** (1748–1830), who became professor of canon law, a post previously held by Jesuits.\n\nWeishaupt was influenced by the French and German Enlightenment. He clashed with former Jesuits on the faculty and came to believe that reform could only be advanced by a disciplined, discreet association of like-minded men who would educate one another and gradually take positions of influence."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-3', 'text', 3, 1, '{}', '{"shared":{"image":"/assets/img/weishaupt.jpg","imagePosition":"right","caption":"Adam Weishaupt (1748–1830), founder of the order."},"en":{"eyebrow":"1 May 1776","heading":"The founding","body":"On 1 May 1776 Weishaupt and a small group of students founded a society first called the **Bund der Perfektibilisten** (\"League of the Perfectibilists\"). Within about two years it was known as the **Illuminatenorden**, the Order of the Illuminati.\n\nMembers took classical code names. Weishaupt was \"Spartacus\", and his early collaborator Franz Xaver von Zwackh was \"Cato\". Cities received code names too: Munich was \"Athens\" and Ingolstadt \"Eleusis\". The order kept its own calendar and required members to read prescribed works and to submit regular written reports on their studies and conduct to their superiors.","buttons":[{"label":"Adam Weishaupt","href":"/figures/adam-weishaupt","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-4', 'text', 4, 1, '{}', '{"shared":{"image":"/assets/img/minerval.jpg","imagePosition":"left","caption":"Title page of Weishaupt’s Das verbesserte System der Illuminaten (1788), with the owl of Minerva."},"en":{"eyebrow":"Structure","heading":"Grades and membership","body":"The early order had three grades: **Novice, Minerval and Illuminated Minerval**. Its emblem was the owl of Minerva, the classical symbol of wisdom.\n\nFrom 1780–82, under the influence of Adolph Freiherr Knigge, the system was greatly expanded and linked to Freemasonry. Knigge''s scheme grouped the grades into three classes:\n\n- a preparatory \"nursery\" (Novice, Minerval, Illuminatus Minor);\n- Masonic grades (the three craft degrees, followed by Illuminatus Major and Illuminatus Dirigens);\n- the \"Mysteries\", lesser (Priest, Regent) and greater (Magus, Rex). The highest grades appear never to have been fully worked out.\n\nRecruitment was selective and often conducted through existing Masonic lodges."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-5', 'text', 5, 1, '{"background":"charcoal"}', '{"shared":{"image":"/assets/img/knigge.jpg","imagePosition":"right","caption":"Adolph Freiherr Knigge (1752–1796)."},"en":{"eyebrow":"1780–1784","heading":"Expansion","body":"Knigge, who joined in 1780 under the name \"Philo\", was a gifted recruiter. Around the time of the Masonic **Convent of Wilhelmsbad** (1782), the order gained a foothold in lodges across the Holy Roman Empire.\n\nMembers included civil servants, professors, clergy, officers and nobles. Documented members include **Duke Ernst II of Saxe-Gotha-Altenburg**, the publisher **Johann Joachim Christoph Bode**, and, in Weimar, **Johann Wolfgang von Goethe** and **Johann Gottfried Herder**, both of whom joined in 1783.\n\nHistorians'' estimates of total membership vary, from several hundred active members to around two thousand people recruited over the order''s lifetime. Internal tensions grew. Knigge and Weishaupt quarrelled over the order''s direction, and Knigge left in **1784**.","buttons":[{"label":"Historical figures","href":"/figures","style":"secondary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-6', 'text', 6, 1, '{}', '{"shared":{"image":"/assets/img/karl-theodor.jpg","imagePosition":"left","caption":"Elector Karl Theodor (1724–1799), who banned the order."},"en":{"eyebrow":"1784–1787","heading":"Government suppression","body":"Elector **Karl Theodor** of Bavaria acted against secret associations in a series of edicts:\n\n- **22 June 1784**: a general prohibition of societies formed without official authorisation;\n- **2 March 1785**: an edict naming and banning the Freemasons and the Illuminati;\n- **16 August 1787**: a further edict renewing the ban under severe penalties.\n\nWeishaupt lost his professorship and left Bavaria in February 1785, eventually settling in Gotha under the protection of Duke Ernst II. In October 1786 the authorities searched the house of Franz Xaver von Zwackh in Landshut and seized correspondence and documents. In 1787 the government published them as *Einige Originalschriften des Illuminatenordens* to expose the order''s aims and methods."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-7', 'text', 7, 1, '{}', '{"shared":{"image":"/assets/img/weishaupt.jpg","imagePosition":"right","caption":"Adam Weishaupt lived in exile in Gotha until his death in 1830."},"en":{"eyebrow":"After 1787","heading":"Disappearance","body":"After the edicts and the publication of its papers, the order ceased to function in Bavaria. Former members elsewhere, notably Bode, tried for a time to keep networks alive, but by the early 1790s there is no evidence of the order operating as an organisation.\n\nWeishaupt published defences of his conduct and lived quietly in Gotha until his death on **18 November 1830**."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-8', 'text', 8, 1, '{"background":"charcoal"}', '{"shared":{"image":"/assets/img/great-seal.jpg","imagePosition":"left","caption":"The Great Seal of the United States (1782), often wrongly linked to the Illuminati."},"en":{"eyebrow":"Interpretations","heading":"Modern interpretations and claims","body":"The order''s afterlife has been far longer than its life.\n\n**Documented history.** In 1797–98 the French Jesuit Augustin Barruel and the Scottish physicist John Robison published influential books arguing that the Illuminati had survived and engineered the French Revolution. Historians have found no evidence for this, but the claim spread quickly. In 1798 it fuelled an \"Illuminati scare\" in New England, led by the minister Jedidiah Morse.\n\n**Later revivals.** In the 1890s, groups in Germany adopted the name (for example Leopold Engel''s *Illuminatenorden*). They had no organisational continuity with the original.\n\n**Popular culture.** In the twentieth century, the Illuminati became a staple of conspiracy theories and fiction, helped by satire such as *The Illuminatus! Trilogy* (1975). Widely repeated claims, for example that the order secretly controls governments or that the pyramid on the U.S. one-dollar bill is its emblem, are **not supported by historical evidence**."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-9', 'timeline_preview', 9, 1, '{}', '{"shared":{"count":6},"en":{"eyebrow":"Timeline","heading":"Key dates","buttons":[{"label":"Full interactive timeline","href":"/timeline","style":"primary"}]}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (2, 'seed-history-10', 'notice', 10, 1, '{}', '{"shared":{"tone":"info"},"en":{"heading":"Sources","body":"- Richard van Dülmen, *Der Geheimbund der Illuminaten. Darstellung, Analyse, Dokumentation* (Stuttgart-Bad Cannstatt: frommann-holzboog, 1975).\n- Manfred Agethen, *Geheimbund und Utopie. Illuminaten, Freimaurer und deutsche Spätaufklärung* (Munich: Oldenbourg, 1984).\n- Hermann Schüttler, *Die Mitglieder des Illuminatenordens 1776–1787/93* (Munich: ars una, 1991).\n- René Le Forestier, *Les Illuminés de Bavière et la franc-maçonnerie allemande* (Paris: Hachette, 1914).\n- Vernon Stauffer, *New England and the Bavarian Illuminati* (New York: Columbia University Press, 1918).\n- Primary source: *Einige Originalschriften des Illuminatenordens* (Munich, 1787), available in our [archive](/archive)."}}');
