INSERT INTO pages (id, slug, name, meta_json, status, in_sitemap, sort, created_at, updated_at, published_at) VALUES (5, 'philosophy', 'Philosophy', '{"title":{"en":"Philosophy","fr":"Philosophie"},"description":{"en":"Reason, education, intellectual freedom and personal development: the Enlightenment traditions behind our work."}}', 'published', 1, 20, 1794301200000, 1794301200000, 1794301200000);
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (5, 'seed-philosophy-0', 'hero', 0, 1, '{}', '{"shared":{"image":"/assets/img/orrery.jpg","height":"large"},"en":{"eyebrow":"Philosophy","heading":"The courage to use one’s own reason","body":"The Enlightenment traditions that inspire our study."},"fr":{"eyebrow":"Philosophie","heading":"Le courage de se servir de sa propre raison","body":"Les traditions des Lumières qui inspirent nos études."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (5, 'seed-philosophy-1', 'text', 1, 1, '{}', '{"shared":{},"en":{"eyebrow":"Reason","heading":"Reason as a shared practice","body":"Eighteenth-century thinkers did not treat reason as a possession of the clever few. For them it was a public practice: arguments are tested in the open, evidence is weighed, and conclusions stay open to revision.\n\nWe try to work the same way. We read primary sources, compare interpretations, and change our minds when the evidence requires it."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (5, 'seed-philosophy-2', 'quote', 2, 1, '{"background":"charcoal","align":"center"}', '{"shared":{"image":"/assets/img/kant.jpg"},"en":{"quote":"Enlightenment is man’s emergence from his self-incurred immaturity. Sapere aude! Have courage to use your own understanding!","attribution":"Immanuel Kant, “An Answer to the Question: What Is Enlightenment?” (1784)"}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (5, 'seed-philosophy-3', 'text', 3, 1, '{}', '{"shared":{"image":"/assets/img/admont-library.jpg","imagePosition":"right"},"en":{"eyebrow":"Education","heading":"Learning for life","body":"The reformers of the 1770s believed that education, more than birth or rank, should shape a person''s place in society. Lifelong learning remains at the centre of our work: reading groups, research notes, shared bibliographies and careful writing."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (5, 'seed-philosophy-4', 'text', 4, 1, '{}', '{"shared":{},"en":{"eyebrow":"Intellectual freedom","heading":"Freedom to inquire","body":"Censorship shaped the world in which the Illuminati were founded and suppressed. We value the freedom to ask difficult questions, and with it the responsibility to answer them honestly, to respect people who disagree, and to distinguish what we know from what we merely suspect."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (5, 'seed-philosophy-5', 'text', 5, 1, '{"background":"charcoal"}', '{"shared":{},"en":{"eyebrow":"Personal development","heading":"Perfectibility, reconsidered","body":"The order''s first name, the *Perfectibilists*, expressed an Enlightenment hope that human beings can improve. We interpret that hope modestly: through discipline, reflection, service and sustained effort, each of us can become wiser and more useful to others than we were."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (5, 'seed-philosophy-6', 'cta', 6, 1, '{"align":"center"}', '{"shared":{},"en":{"heading":"Explore our principles","body":"Six commitments that guide the modern Covenant.","buttons":[{"label":"Our principles","href":"/principles","style":"primary"}]}}');
