INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (7, 'seed-symbols-1', 'notice', 1, 1, '{"spacing":"compact"}', '{"shared":{"tone":"caution"},"en":{"heading":"Fact and speculation","body":"Many symbols popularly linked to the \"Illuminati\" were never used by the Bavarian order. For each symbol we state its documented origin first, then later interpretations, clearly labelled. Unsupported conspiracy theories are described as claims, not facts."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (7, 'seed-symbols-2', 'symbols_list', 2, 1, '{}', '{"shared":{},"en":{}}');
INSERT INTO pages (id, slug, name, meta_json, status, in_sitemap, sort, created_at, updated_at, published_at) VALUES (8, 'covenant', 'The Covenant', '{"title":{"en":"The Covenant","fr":"Le Covenant"},"description":{"en":"Who we are: the identity, mission, vision, governance and activities of the Eternal Illuminati Covenant."}}', 'published', 1, 30, 1794301200000, 1794301200000, 1794301200000);
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (8, 'seed-covenant-0', 'hero', 0, 1, '{}', '{"shared":{"image":"/assets/img/pantheon.jpg","height":"medium"},"en":{"eyebrow":"Who we are","heading":"The Covenant","body":"An independent, modern organisation, open about what it is and what it is not."},"fr":{"eyebrow":"Qui sommes-nous","heading":"Le Covenant","body":"Une organisation moderne et indépendante, transparente sur ce qu''elle est et ce qu''elle n''est pas."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (8, 'seed-covenant-1', 'text', 1, 1, '{}', '{"shared":{},"en":{"eyebrow":"Identity","heading":"What we are","body":"The Eternal Illuminati Covenant is an **independently established, modern organisation**. It takes its inspiration from the Enlightenment and studies the history of the Bavarian Illuminati.\n\n**What we are not:**\n\n- We are not the Bavarian Illuminati, and we claim no historical continuity with them.\n- We are not connected to any other organisation using the word \"Illuminati\".\n- We do not offer wealth, fame, power, protection or influence, and we never ask for money in exchange for such promises."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (8, 'seed-covenant-2', 'text', 2, 1, '{"background":"charcoal"}', '{"shared":{},"en":{"eyebrow":"Mission","heading":"Our mission","body":"To promote the study of the Enlightenment and of the Bavarian Illuminati through careful, source-based research, and to support members in lifelong learning, critical thinking and personal development."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (8, 'seed-covenant-3', 'text', 3, 1, '{}', '{"shared":{},"en":{"eyebrow":"Vision","heading":"Our vision","body":"A community in which curiosity, reason and integrity are practised together, and in which history is studied honestly rather than mythologised."}}');
