INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-1', 'text', 1, 1, '{}', '{"shared":{},"en":{"eyebrow":"What we represent","heading":"A community of study","body":"Members share an interest in the Enlightenment, in the history of the Bavarian Illuminati, and in personal development through learning. Membership means taking part in that work: reading, discussing, writing and helping others learn."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-2', 'text', 2, 1, '{"background":"charcoal"}', '{"shared":{},"en":{"eyebrow":"Eligibility","heading":"Who may apply","body":"- Adults aged **18 or over**.\n- From any country, background or belief.\n- With a genuine interest in history, philosophy and self-improvement.\n- Willing to follow our [Code of Conduct](/code-of-conduct)."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-3', 'text', 3, 1, '{}', '{"shared":{},"en":{"eyebrow":"Requirements","heading":"What the application asks","body":"The application has four steps: personal information, background, motivation, and a final review. It takes about 15–20 minutes. You may attach up to three supporting documents, but you do not have to. **Applying is free**, and you do not need to create an account."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-4', 'text', 4, 1, '{"background":"charcoal"}', '{"shared":{},"en":{"eyebrow":"Expectations","heading":"What is expected of members","body":"- Honesty and respect towards other members and the public.\n- Willingness to learn and to share knowledge.\n- Care in distinguishing fact from speculation.\n- Discretion about other members'' personal information."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-5', 'text', 5, 1, '{}', '{"shared":{},"en":{"eyebrow":"Review","heading":"How applications are reviewed","body":"1. You confirm your email address using the link we send you.\n2. An authorised reviewer reads your application.\n3. We may email you to ask for more information.\n4. You receive a decision by email.\n\nReview times vary. You will receive an email at each important stage."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-6', 'text', 6, 1, '{"background":"charcoal"}', '{"shared":{},"en":{"eyebrow":"Privacy","heading":"Privacy and confidentiality","body":"Applications are visible only to authorised administrators. They are never published, sold or used for marketing. Unconfirmed applications are deleted automatically after 7 days. See our [Privacy Policy](/privacy) and [Data Protection](/data-protection) pages."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-7', 'notice', 7, 1, '{}', '{"shared":{"tone":"caution"},"en":{"heading":"What membership does not offer","body":"Membership does **not** bring wealth, fame, power, political influence, business advantages, protection or access to \"elite\" networks. **We will never ask you for money transfers, gift cards, cryptocurrency or banking details by email or social media.** If anyone makes such offers in our name, please [report it](/report)."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (10, 'seed-membership-8', 'cta', 8, 1, '{"align":"center"}', '{"shared":{},"en":{"heading":"Ready to apply?","body":"It takes about 15 minutes and you can save your progress.","buttons":[{"label":"Start your application","href":"/apply","style":"primary"}]}}');
INSERT INTO pages (id, slug, name, meta_json, status, in_sitemap, sort, created_at, updated_at, published_at) VALUES (11, 'apply', 'Apply', '{"title":{"en":"Apply for Membership","fr":"Candidater"},"description":{"en":"Apply to join the Eternal Illuminati Covenant. No account needed."}}', 'published', 1, 41, 1794301200000, 1794301200000, 1794301200000);
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (11, 'seed-apply-0', 'hero', 0, 1, '{}', '{"shared":{"height":"medium","image":"/assets/img/admont-library.jpg"},"en":{"eyebrow":"Membership","heading":"Apply for membership","body":"Four short steps. No account needed. Your progress can be saved and finished later."},"fr":{"eyebrow":"Adhésion","heading":"Candidater","body":"Quatre étapes. Aucun compte nécessaire. Vous pouvez enregistrer et terminer plus tard."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (11, 'seed-apply-1', 'application_form', 1, 1, '{}', '{"shared":{},"en":{"heading":"","intro":"Before you begin, please read the [membership information](/membership) and the [application guide](/application-guide). Fields marked * are required."},"fr":{"intro":"Avant de commencer, veuillez lire les [informations sur l''adhésion](/membership) et le [guide de candidature](/application-guide). Les champs marqués * sont obligatoires."}}');
INSERT INTO pages (id, slug, name, meta_json, status, in_sitemap, sort, created_at, updated_at, published_at) VALUES (12, 'application-guide', 'Application Guide', '{"title":{"en":"Application Guide","fr":"Guide de candidature"},"description":{"en":"Step-by-step guidance for completing a membership application."}}', 'published', 1, 42, 1794301200000, 1794301200000, 1794301200000);
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (12, 'seed-application-guide-0', 'hero', 0, 1, '{}', '{"shared":{"height":"medium"},"en":{"eyebrow":"Guide","heading":"Application guide","body":"How to complete each step, and what happens next."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (12, 'seed-application-guide-1', 'text', 1, 1, '{}', '{"shared":{},"en":{"heading":"Step by step","body":"**Step 1: Personal information.** Your name, email address and country. Use an email address you check regularly: everything we send goes there.\n\n**Step 2: Background.** Your occupation, relevant experience and interests. There are no \"right\" answers, and formal qualifications are not required.\n\n**Step 3: Motivation.** Why you want to apply, what you understand about the Covenant, and what you hope to contribute. Please write in your own words.\n\n**Step 4: Review and submit.** Check your answers, read the privacy notice, and confirm your consent. You can go back to correct anything.\n\n**Save and continue later.** Use \"Save and continue later\" at any point. We will email you a private link that is valid for 7 days.\n\n**After you submit.** We will email you a link to confirm your address. Your application is reviewed only after you confirm it, and unconfirmed applications are deleted after 7 days.\n\n**Questions or changes.** Use the form on our [contact page](/contact) with your reference number. You can also withdraw your application there at any time."}}');
INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (12, 'seed-application-guide-2', 'cta', 2, 1, '{"align":"center","background":"charcoal"}', '{"shared":{},"en":{"heading":"Begin your application","buttons":[{"label":"Apply now","href":"/apply","style":"primary"}]}}');
