INSERT INTO page_sections (page_id, uid, type, sort, visible, settings_json, content_json) VALUES (17, 'seed-contact-1', 'contact_form', 1, 1, '{}', '{"shared":{},"en":{"eyebrow":"General enquiries","heading":"Send a message","intro":"We aim to reply to every genuine message. Please do not send passwords, banking details or identity documents through this form."},"fr":{"eyebrow":"Demandes générales","heading":"Envoyer un message","intro":"Nous nous efforçons de répondre à chaque message. N''envoyez ni mot de passe, ni coordonnées bancaires, ni pièce d''identité via ce formulaire."}}');
