INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('birth-of-adam-weishaupt', '6 February 1748', 1748, 'Before the order', 'Birth of Adam Weishaupt', 'Johann Adam Weishaupt is born in Ingolstadt, Bavaria. Orphaned young, he is raised under the guidance of his godfather, the jurist Johann Adam von Ickstatt.', 'Weishaupt was educated at a Jesuit school and later studied at the University of Ingolstadt, where his godfather, the reform-minded jurist Johann Adam Freiherr von Ickstatt, was an influential figure.', '/assets/img/weishaupt.jpg', 'Portrait of Adam Weishaupt', '- van Dülmen (1975).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Avant l''ordre","title":"Naissance d''Adam Weishaupt","date_label":"6 février 1748","summary":"Johann Adam Weishaupt naît à Ingolstadt, en Bavière. Orphelin jeune, il est élevé sous la tutelle de son parrain, le juriste Johann Adam von Ickstatt."}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('suppression-of-the-jesuits', '21 July 1773', 1773, 'Before the order', 'The Jesuits are suppressed', 'Pope Clement XIV dissolves the Society of Jesus. At Ingolstadt, Weishaupt takes the chair of canon law, a post previously held by Jesuits.', 'The papal brief *Dominus ac Redemptor* suppressed the Jesuit order, which had dominated higher education in Bavaria. The resulting vacancies opened academic posts to lay scholars such as Weishaupt, and fuelled lasting tensions between former Jesuits and reformers at the university.', '', '', '- van Dülmen (1975); Agethen (1984).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Avant l''ordre","title":"Suppression des jésuites","date_label":"21 juillet 1773"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('founding-of-the-order', '1 May 1776', 1776, 'The order', 'Founding of the order', 'Weishaupt and a small group of students found the "Bund der Perfektibilisten", soon to be known as the Order of the Illuminati.', 'The founding meeting took place in Ingolstadt. The society began very small and recruited cautiously among students and young officials. Members adopted classical code names; Weishaupt was "Spartacus".', '/assets/img/ingolstadt.jpg', 'The former university building (Hohe Schule) in Ingolstadt', '- Richard van Dülmen, *Der Geheimbund der Illuminaten. Darstellung, Analyse, Dokumentation* (Stuttgart-Bad Cannstatt: frommann-holzboog, 1975).
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('weishaupt-becomes-a-freemason', '1777', 1777, 'The order', 'Weishaupt becomes a Freemason', 'Weishaupt is initiated into Freemasonry in Munich, beginning the long, uneasy relationship between the order and Masonic lodges.', 'Weishaupt hoped that Masonic lodges would provide cover and recruits. Later the order would systematically recruit within lodges.', '', '', '- Agethen (1984).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"L''ordre","title":"Weishaupt devient franc-maçon","date_label":"1777"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('knigge-joins', '1780', 1780, 'The order', 'Adolph Knigge joins', 'The writer and Freemason Adolph Freiherr Knigge ("Philo") joins and begins reorganising the order’s grades and recruiting widely.', 'Knigge brought energy, Masonic contacts and a systematic structure of grades. His reforms of 1781–82 greatly expanded the order.', '/assets/img/knigge.jpg', 'Portrait of Adolph Freiherr Knigge', '- van Dülmen (1975).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"L''ordre","title":"Adhésion d''Adolph Knigge","date_label":"1780"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('convent-of-wilhelmsbad', 'July–September 1782', 1782, 'The order', 'Convent of Wilhelmsbad', 'A major congress of German Freemasonry meets at Wilhelmsbad near Hanau. The Illuminati use the period to extend their influence among lodges.', 'The convent addressed the future of the Strict Observance rite. Illuminati recruiters, Knigge above all, used the upheaval to win members.', '', '', '- Le Forestier (1914); Agethen (1984).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"L''ordre","title":"Convent de Wilhelmsbad","date_label":"juillet–septembre 1782"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('goethe-and-herder-join', '1783', 1783, 'The order', 'Goethe and Herder join in Weimar', 'Johann Wolfgang von Goethe (as "Abaris") and Johann Gottfried Herder join the order in Weimar.', 'Their membership is documented in the order’s records. Historians debate how active either man was; neither played a leading role.', '/assets/img/goethe.jpg', 'Portrait of Johann Wolfgang von Goethe', '- Schüttler (1991); W. Daniel Wilson, *Geheimräte gegen Geheimbünde* (Stuttgart: Metzler, 1991).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"L''ordre","title":"Goethe et Herder rejoignent l’ordre à Weimar","date_label":"1783"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('first-edict', '22 June 1784', 1784, 'Suppression', 'First edict against secret societies', 'Elector Karl Theodor prohibits all societies formed without official authorisation.', 'The edict did not name the Illuminati, but it signalled growing official hostility to clandestine associations in Bavaria.', '/assets/img/karl-theodor.jpg', 'Portrait of Elector Karl Theodor', '- van Dülmen (1975).', 'documented', 1, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Répression","title":"Premier édit contre les sociétés secrètes","date_label":"22 juin 1784"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('knigge-leaves', '1784', 1784, 'The order', 'Knigge leaves the order', 'After bitter disputes with Weishaupt over leadership and direction, Knigge withdraws from the order.', 'The quarrel concerned authority within the order and the content of its higher grades.', '', '', '- van Dülmen (1975).', 'documented', 2, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"L''ordre","title":"Knigge quitte l''ordre","date_label":"1784"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('second-edict', '2 March 1785', 1785, 'Suppression', 'The Illuminati are banned by name', 'A second edict explicitly prohibits the Freemasons and the Illuminati in Bavaria. Weishaupt has already lost his post and left Ingolstadt.', 'Weishaupt fled in February 1785, first to Regensburg and later to Gotha. Members in state service faced dismissal.', '', '', '- van Dülmen (1975).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Répression","title":"Les Illuminés interdits nommément","date_label":"2 mars 1785"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('the-courier-and-the-lightning', '1785', 1785, 'Suppression', 'The courier struck by lightning', 'A popular story holds that a courier carrying the order’s papers was killed by lightning near Regensburg, exposing its secrets.', 'A cleric named Lanz is reported to have died after a lightning strike in 1785. The claim that papers found on him exposed the order is a later tradition, and it is poorly supported. The decisive documents were seized in the 1786 search of Zwackh’s house.', '', '', '', 'legend', 2, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Répression","title":"Le courrier foudroyé","date_label":"1785"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('search-of-zwackhs-house', '11–12 October 1786', 1786, 'Suppression', 'Search of Zwackh’s house', 'Authorities search the house of Franz Xaver von Zwackh in Landshut and seize the order’s correspondence and documents.', 'The seized papers included letters, statutes and lists. They gave the government material to discredit the order.', '', '', '- *Einige Originalschriften des Illuminatenordens* (Munich, 1787).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Répression","title":"Perquisition chez Zwackh","date_label":"11–12 octobre 1786"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('publication-of-the-original-writings', '1787', 1787, 'Suppression', 'The order’s papers are published', 'The Bavarian government prints the seized documents as *Einige Originalschriften des Illuminatenordens*. A third edict (16 August 1787) renews the ban.', 'Publication was meant to expose the order publicly. It also preserved the order’s papers, which became key sources for historians.', '/assets/img/minerval.jpg', 'Title page of Das verbesserte System der Illuminaten (1788)', '- *Einige Originalschriften des Illuminatenordens* (Munich, 1787).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Répression","title":"Publication des écrits de l''ordre","date_label":"1787"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('barruel-and-robison', '1797–1798', 1797, 'Afterlife & myth', 'Barruel and Robison', 'Augustin Barruel and John Robison publish books claiming the Illuminati survived and caused the French Revolution.', 'These works shaped the conspiracy-theory image of the Illuminati for two centuries. Historians find no evidence that the suppressed order survived or directed the Revolution.', '', 'Title page of John Robison’s Proofs of a Conspiracy', '- John Robison, *Proofs of a Conspiracy* (Edinburgh, 1797).
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('new-england-illuminati-scare', '1798', 1798, 'Afterlife & myth', 'The New England "Illuminati scare"', 'Sermons by Jedidiah Morse spread fears of Illuminati subversion in the United States.', 'The episode is the subject of Vernon Stauffer’s classic study. It shows how quickly the claim travelled and how it was used in partisan politics.', '', '', '- Stauffer (1918).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Postérité et mythe","title":"La « peur des Illuminés » en Nouvelle-Angleterre","date_label":"1798"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('death-of-weishaupt', '18 November 1830', 1830, 'Afterlife & myth', 'Death of Adam Weishaupt', 'Weishaupt dies in Gotha, where he had lived since the 1780s under the protection of Duke Ernst II.', 'In exile he published several works defending himself and the order’s intentions.', '', '', '- van Dülmen (1975).', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Postérité et mythe","title":"Mort d''Adam Weishaupt","date_label":"18 novembre 1830"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('later-revivals', '1890s', 1896, 'Afterlife & myth', 'Revivals in name only', 'Groups in Germany, including Leopold Engel’s Illuminatenorden, adopt the name. None has any organisational continuity with the original order.', 'Such revivals show the enduring attraction of the name. They should not be confused with the eighteenth-century order.', '', '', '', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Postérité et mythe","title":"Des renaissances de nom seulement","date_label":"années 1890"}}');
INSERT INTO historical_events (slug, date_label, year, era, title, summary, body, image, image_alt, sources, certainty, sort, status, created_at, updated_at, i18n_json) VALUES ('illuminatus-trilogy', '1975', 1975, 'Afterlife & myth', '"The Illuminatus! Trilogy"', 'Robert Shea and Robert Anton Wilson publish satirical novels that help turn the Illuminati into a fixture of popular culture.', 'The trilogy parodied conspiracy thinking, yet it did much to spread Illuminati imagery in the late twentieth century.', '', '', '', 'documented', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"era":"Postérité et mythe","title":"« The Illuminatus! Trilogy »","date_label":"1975"}}');
INSERT INTO historical_figures (slug, name, role_title, dates_label, portrait, portrait_alt, summary, background, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('adam-weishaupt', 'Adam Weishaupt', 'Founder of the Order of the Illuminati', '1748–1830', '/assets/img/weishaupt.jpg', 'Engraved portrait of Adam Weishaupt', 'Professor of canon law at Ingolstadt who founded the order on 1 May 1776 under the code name "Spartacus".', 'Born in Ingolstadt and educated by Jesuits, Weishaupt became professor of canon law at the university there after the suppression of the Jesuits in 1773.', 'Weishaupt''s ambition was to create a society of educated, morally disciplined men who would spread Enlightenment values and gradually reform society from within. He directed the order closely, often in conflict with other leaders, most notably Adolph Knigge.
INSERT INTO historical_figures (slug, name, role_title, dates_label, portrait, portrait_alt, summary, background, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('adolph-knigge', 'Adolph Freiherr Knigge', 'Writer, Freemason and reorganiser of the order', '1752–1796', '/assets/img/knigge.jpg', 'Engraved portrait of Adolph Freiherr Knigge', 'Joined in 1780 as "Philo", reorganised the order’s grades and led its expansion before leaving in 1784.', 'A Hanoverian nobleman and Freemason, Knigge is best known today for his book *Über den Umgang mit Menschen* ("On Human Relations", 1788).', 'Knigge used his Masonic network to recruit widely and drafted much of the expanded grade system adopted in 1781–82. Disputes with Weishaupt over authority and the content of the higher grades led to his departure in 1784. He died in Bremen in 1796.', '- van Dülmen (1975).
INSERT INTO historical_figures (slug, name, role_title, dates_label, portrait, portrait_alt, summary, background, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('franz-xaver-von-zwackh', 'Franz Xaver von Zwackh', 'Early member and Bavarian official', '1756–1843', '', '', 'One of the earliest members ("Cato"). The 1786 search of his house in Landshut exposed the order’s papers.', 'Zwackh was a law student and later a government official in Bavaria.', 'As one of Weishaupt’s closest early collaborators, Zwackh kept much of the order’s correspondence. When authorities searched his house in Landshut on 11–12 October 1786, these papers were seized and published the following year.', '- *Einige Originalschriften des Illuminatenordens* (Munich, 1787).
INSERT INTO historical_figures (slug, name, role_title, dates_label, portrait, portrait_alt, summary, background, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('johann-joachim-christoph-bode', 'Johann Joachim Christoph Bode', 'Publisher, translator and Freemason', '1731–1793', '/assets/img/bode.jpg', 'Portrait of Johann Joachim Christoph Bode', 'A Weimar publisher and translator who joined in 1782 and tried to sustain the order’s networks after its suppression.', 'Bode was a musician, publisher and celebrated translator of English and French literature into German, including Sterne and Montaigne.', 'A prominent Freemason, Bode joined the Illuminati in 1782 and became one of its leading figures outside Bavaria. After the Bavarian ban he worked to preserve contacts among former members, but without lasting success. He died in Weimar in 1793.', '- Schüttler (1991).
INSERT INTO historical_figures (slug, name, role_title, dates_label, portrait, portrait_alt, summary, background, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('ernst-ii-of-saxe-gotha-altenburg', 'Ernst II, Duke of Saxe-Gotha-Altenburg', 'Reigning duke, patron of science, member of the order', '1745–1804', '/assets/img/ernst-ii.jpg', 'Portrait of Duke Ernst II of Saxe-Gotha-Altenburg', 'An enlightened ruler and patron of astronomy who joined the order and gave Weishaupt refuge in Gotha.', 'Duke from 1772, Ernst II promoted science and education and founded the Seeberg observatory near Gotha.', 'Ernst II joined the order in 1783. After Weishaupt left Bavaria, the duke offered him protection and a position in Gotha, where Weishaupt lived for the rest of his life.', '- Schüttler (1991).
INSERT INTO historical_figures (slug, name, role_title, dates_label, portrait, portrait_alt, summary, background, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('johann-wolfgang-von-goethe', 'Johann Wolfgang von Goethe', 'Poet and Weimar statesman; member from 1783', '1749–1832', '/assets/img/goethe.jpg', 'Portrait of Goethe by Joseph Karl Stieler, 1828', 'Joined the order in Weimar in 1783 under the name "Abaris". His involvement appears to have been limited.', 'Already a celebrated author and a minister in the Duchy of Saxe-Weimar, Goethe was also a Freemason.', 'Goethe’s membership is documented, but historians have long debated its significance. Research by W. Daniel Wilson suggests that leading Weimar officials may have joined partly to keep the order under observation. There is no evidence that Goethe played a leading role.', '- W. Daniel Wilson, *Geheimräte gegen Geheimbünde* (Stuttgart: Metzler, 1991).
INSERT INTO historical_figures (slug, name, role_title, dates_label, portrait, portrait_alt, summary, background, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('karl-theodor-elector-of-bavaria', 'Karl Theodor, Elector of Bavaria', 'Ruler who banned the order', '1724–1799', '/assets/img/karl-theodor.jpg', 'Portrait of Elector Karl Theodor by Pompeo Batoni', 'Elector Palatine and, from 1777, Elector of Bavaria. His edicts of 1784, 1785 and 1787 suppressed the Illuminati.', 'Karl Theodor inherited Bavaria in 1777. He was a patron of the arts and sciences but suspicious of secret associations.', 'Through three edicts, Karl Theodor first banned unauthorised societies (1784), then named and prohibited the Freemasons and the Illuminati (1785), and finally renewed the ban with severe penalties (1787).', '- van Dülmen (1975).', 6, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO principles (slug, title, summary, body, image, image_alt, sort, status, created_at, updated_at, i18n_json) VALUES ('knowledge-and-education', 'Knowledge and Education', 'We value careful learning over easy certainty, and study as a lifelong practice.', 'Members commit to reading widely, citing sources, and sharing what they learn. We prefer primary sources and serious scholarship to rumour, and we treat education as something that continues throughout life.', '', '', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"title":"Savoir et éducation","summary":"Nous préférons l''apprentissage patient aux certitudes faciles, et l''étude comme pratique de toute une vie."}}');
INSERT INTO principles (slug, title, summary, body, image, image_alt, sort, status, created_at, updated_at, i18n_json) VALUES ('independent-thinking', 'Independent Thinking', 'We test claims against evidence, including our own.', 'Independent thinking means being willing to question authority, popular opinion and our own assumptions, and to change our minds when the evidence requires it. It does not mean contrarianism: we follow the evidence wherever it leads.', '', '', 1, 'published', 1794301200000, 1794301200000, '{"fr":{"title":"Pensée indépendante","summary":"Nous confrontons les affirmations aux preuves, y compris les nôtres."}}');
INSERT INTO principles (slug, title, summary, body, image, image_alt, sort, status, created_at, updated_at, i18n_json) VALUES ('discipline-and-character', 'Discipline and Character', 'Good intentions become good work through steady habits.', 'Discipline turns curiosity into knowledge. We encourage members to set goals for their study, keep commitments to one another, and build character through consistent effort rather than display.', '', '', 2, 'published', 1794301200000, 1794301200000, '{"fr":{"title":"Discipline et caractère","summary":"Les bonnes intentions deviennent du bon travail grâce à des habitudes régulières."}}');
INSERT INTO principles (slug, title, summary, body, image, image_alt, sort, status, created_at, updated_at, i18n_json) VALUES ('integrity-and-responsibility', 'Integrity and Responsibility', 'We say what we know, admit what we do not, and keep our promises.', 'Integrity is central to an organisation whose subject attracts myth and fraud. We never claim powers, connections or benefits we do not have, and we hold ourselves responsible for the accuracy of what we publish and the way we treat others.', '', '', 3, 'published', 1794301200000, 1794301200000, '{"fr":{"title":"Intégrité et responsabilité","summary":"Nous disons ce que nous savons, reconnaissons ce que nous ignorons, et tenons nos promesses."}}');
INSERT INTO principles (slug, title, summary, body, image, image_alt, sort, status, created_at, updated_at, i18n_json) VALUES ('personal-development', 'Personal Development', 'Each of us can become wiser, kinder and more capable than we were.', 'Inspired by the Enlightenment idea of human perfectibility, we see personal development as patient, practical work: reflection, study, conversation and service.', '', '', 4, 'published', 1794301200000, 1794301200000, '{"fr":{"title":"Développement personnel","summary":"Chacun peut devenir plus sage, plus bienveillant et plus capable."}}');
INSERT INTO principles (slug, title, summary, body, image, image_alt, sort, status, created_at, updated_at, i18n_json) VALUES ('service-to-society', 'Service to Society', 'Knowledge is worth most when it is shared for the common good.', 'We aim to contribute to public understanding of history and philosophy: through accurate publications, open resources, and members’ service in their own communities.', '', '', 5, 'published', 1794301200000, 1794301200000, '{"fr":{"title":"Service à la société","summary":"Le savoir vaut davantage lorsqu’il est partagé pour le bien commun."}}');
INSERT INTO symbols (slug, name, image, image_alt, origin, summary, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('owl-of-minerva', 'The Owl of Minerva', '/assets/img/minerval.jpg', 'Owl of Minerva emblem on the title page of Das verbesserte System der Illuminaten (1788)', 'Classical antiquity; used by the Bavarian Illuminati (documented)', 'The owl of Athena/Minerva symbolised wisdom in the ancient world. The Bavarian Illuminati used it on the insignia of their Minerval grade, the order’s core student-like rank.', '**Documented use.** The owl appears on the insignia of the Minerval grade. Members of that grade were called "Minervals" and met in "Minerval churches".
INSERT INTO symbols (slug, name, image, image_alt, origin, summary, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('eye-of-providence', 'The Eye of Providence', '', '', 'Christian art, from the Renaissance onward', 'An eye within a triangle, representing the watchful care of God (the triangle evoking the Trinity). It appears in Christian art from the sixteenth century.', '**Documented history.** The motif appears in European religious art from the Renaissance. It was adopted in Freemasonry in the late eighteenth century, and in 1782 it was placed above the unfinished pyramid on the reverse of the Great Seal of the United States.
INSERT INTO symbols (slug, name, image, image_alt, origin, summary, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('unfinished-pyramid', 'The Unfinished Pyramid', '/assets/img/great-seal.jpg', 'Obverse and reverse of the Great Seal of the United States', 'Great Seal of the United States, reverse (1782)', 'A thirteen-step unfinished pyramid beneath the Eye of Providence, with the date MDCCLXXVI (1776) and the mottoes Annuit Coeptis and Novus Ordo Seclorum.', '**Documented history.** The reverse of the Great Seal was adopted by Congress in 1782. The date 1776 refers to the Declaration of Independence. The mottoes come from Virgil, and the thirteen steps represent the original states. The design has appeared on the one-dollar bill since 1935.
INSERT INTO symbols (slug, name, image, image_alt, origin, summary, body, sources, sort, status, created_at, updated_at, i18n_json) VALUES ('light-and-illumination', 'Light and Illumination', '/assets/img/orrery.jpg', 'Joseph Wright of Derby, A Philosopher Lecturing on the Orrery', 'Enlightenment metaphor (Aufklärung, Lumières)', 'Light as a metaphor for knowledge runs through the eighteenth century and gives the "Illuminati" (the enlightened ones) their name.', '**Documented history.** The German *Aufklärung*, the French *Lumières* and the English *Enlightenment* all draw on the image of light dispelling darkness. Long before 1776, the Latin word *illuminati* had been applied to various religious and mystical groups, for example the Spanish *alumbrados* of the sixteenth century.
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('are-you-the-bavarian-illuminati', 'Are you the Bavarian Illuminati?', 'No. The Bavarian Illuminati were founded in 1776 and suppressed in the 1780s. The Eternal Illuminati Covenant is an independent, modern organisation that studies that history. It claims no historical continuity with the original order.', 'general', 0, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"Êtes-vous les Illuminés de Bavière ?","answer":"Non. Les Illuminés de Bavière ont été fondés en 1776 et réprimés dans les années 1780. L''Eternal Illuminati Covenant est une organisation moderne et indépendante qui étudie cette histoire, sans revendiquer de continuité historique."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('does-membership-bring-wealth-or-power', 'Will membership bring me wealth, power or protection?', 'No. Membership offers study, discussion and fellowship. It brings no financial, political or professional advantage. Anyone who promises otherwise in our name is not acting for us. Please [report it](/report).', 'membership', 1, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"L''adhésion apporte-t-elle richesse, pouvoir ou protection ?","answer":"Non. L''adhésion offre l''étude, la discussion et la fraternité, sans aucun avantage financier, politique ou professionnel. Toute personne promettant le contraire en notre nom n''agit pas pour nous : [signalez-le](/report)."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('someone-asked-me-for-money', 'Someone contacted me offering membership in exchange for money. Is it real?', 'Applications are made only through this website, and applying is free. We never ask for money transfers, gift cards, cryptocurrency or banking details by email, phone or social media. Please do not pay, and [report the contact](/report).', 'membership', 2, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"Quelqu''un m''a proposé une adhésion contre de l''argent. Est-ce réel ?","answer":"Les candidatures se font uniquement sur ce site et sont gratuites. Nous ne demandons jamais de virement, carte cadeau, cryptomonnaie ou coordonnées bancaires. Ne payez pas et [signalez ce contact](/report)."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('is-there-a-fee-to-apply', 'Is there a fee to apply?', 'No. Submitting an application is free.', 'membership', 3, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"Faut-il payer pour candidater ?","answer":"Non. Le dépôt de candidature est gratuit."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('how-is-my-data-used', 'Who can see my application?', 'Only authorised administrators. Applications are never published or shared for marketing. See our [Privacy Policy](/privacy).', 'privacy', 4, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"Qui peut voir ma candidature ?","answer":"Uniquement les administrateurs autorisés. Les candidatures ne sont jamais publiées ni partagées à des fins commerciales. Voir notre [politique de confidentialité](/privacy)."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('can-i-withdraw', 'Can I withdraw my application?', 'Yes, at any time. Use the withdrawal form on our [contact page](/contact) with your reference number and email address. We will email you a link to confirm.', 'membership', 5, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"Puis-je retirer ma candidature ?","answer":"Oui, à tout moment, via le formulaire de retrait de la [page contact](/contact), avec votre référence et votre adresse e-mail."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('how-long-does-review-take', 'How long does the review take?', 'It varies with the number of applications. You will receive an email at each important stage, and we may contact you if we need more information.', 'membership', 6, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"Combien de temps dure l''examen ?","answer":"Cela dépend du nombre de candidatures. Vous recevrez un e-mail à chaque étape importante."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('did-the-illuminati-cause-the-french-revolution', 'Did the Illuminati cause the French Revolution?', 'No evidence supports this. The claim was popularised in 1797–98 by Augustin Barruel and John Robison, after the order had already been suppressed. Historians reject it.', 'history', 7, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"Les Illuminés ont-ils causé la Révolution française ?","answer":"Aucune preuve ne l''atteste. Cette thèse a été popularisée en 1797–1798 par Barruel et Robison, après la répression de l''ordre ; les historiens la rejettent."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('is-the-dollar-pyramid-an-illuminati-symbol', 'Is the pyramid on the dollar bill an Illuminati symbol?', 'No. The pyramid and the Eye of Providence come from the reverse of the Great Seal of the United States, adopted in 1782. The date 1776 refers to the Declaration of Independence. See [The Unfinished Pyramid](/symbols/unfinished-pyramid).', 'history', 8, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"La pyramide du dollar est-elle un symbole des Illuminés ?","answer":"Non. La pyramide et l''œil de la Providence proviennent du revers du grand sceau des États-Unis (1782) ; la date 1776 renvoie à la Déclaration d''indépendance."}}');
INSERT INTO faqs (slug, question, answer, category, sort, status, created_at, updated_at, i18n_json) VALUES ('does-the-illuminati-still-exist', 'Does the original order still exist?', 'There is no evidence that the Bavarian order survived beyond the late 1780s or early 1790s. Later groups that used the name had no organisational continuity with it.', 'history', 9, 'published', 1794301200000, 1794301200000, '{"fr":{"question":"L''ordre originel existe-t-il encore ?","answer":"Rien n''indique que l''ordre bavarois ait survécu au-delà de la fin des années 1780 ou du début des années 1790."}}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('einige-originalschriften-1787', 'Einige Originalschriften des Illuminatenordens (1787)', 'document', 'Primary sources', '1787', 'The order’s papers seized at Zwackh’s house in Landshut in October 1786 and published by the Bavarian government to expose the order.', 'This volume is the single most important primary source for the inner workings of the order: letters, statutes and plans. Read it critically. It was published by the order’s opponents, who chose what to print.', '', 'Title page, 1787', '', '', 0, 'Public domain', 'Internet Archive scan, via Wikimedia Commons', 0, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('nachtrag-von-weitern-originalschriften-1787', 'Nachtrag von weitern Originalschriften (1787)', 'document', 'Primary sources', '1787', 'A supplementary volume of documents published in 1787, continuing the government’s exposure of the order.', 'Published as a sequel to the *Originalschriften*, with further correspondence and documents.', '', '', '', 'https://archive.org/details/nachtragvonweite121duke', 0, 'Public domain', 'Duke University Libraries, via Internet Archive', 1, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('robison-proofs-of-a-conspiracy-1797', 'John Robison, Proofs of a Conspiracy (1797)', 'reference', 'Conspiracy literature', '1797', 'An influential work claiming that Freemasons, the Illuminati and reading societies conspired against the religions and governments of Europe.', 'Robison was a respected professor of natural philosophy at Edinburgh. His book is important evidence of how the Illuminati myth spread, but it is **not** a reliable account of the order itself.', '', 'Title page of Proofs of a Conspiracy', '', 'https://archive.org/details/proofsofconspira00robi', 0, 'Public domain', 'Internet Archive', 2, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('barruel-memoires-jacobinisme', 'Augustin Barruel, Mémoires pour servir à l’histoire du Jacobinisme (1797–98)', 'reference', 'Conspiracy literature', '1797–1798', 'Four volumes arguing that the French Revolution resulted from a conspiracy of philosophes, Freemasons and Illuminati.', 'Together with Robison, Barruel created the template for later Illuminati conspiracy theories. Historians regard his central thesis as unsupported.', '', '', '', '', 0, 'Public domain', '', 3, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('das-verbesserte-system-der-illuminaten-1788', 'Adam Weishaupt, Das verbesserte System der Illuminaten (1788)', 'document', 'Primary sources', '1788', 'Weishaupt’s own account of the order’s “improved system” with all its grades, published in exile. The title page carries the owl of Minerva emblem.', 'A key apologetic source: Weishaupt presents the order as he wished it to be understood after its suppression. Read it alongside the government’s *Originalschriften*.', '/assets/img/minerval.jpg', 'Title page with the owl of Minerva emblem', '', 'https://commons.wikimedia.org/wiki/File:Minerval_insignia.png', 0, 'Public domain', 'Wikimedia Commons', 4, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('great-seal-of-the-united-states', 'Great Seal of the United States (obverse and reverse)', 'photograph', 'Images', '1782', 'The seal whose reverse shows the unfinished pyramid and the Eye of Providence, a design often wrongly attributed to the Illuminati.', 'See our essay on [the unfinished pyramid](/symbols/unfinished-pyramid).', '/assets/img/great-seal.jpg', 'Great Seal obverse and reverse', '', 'https://commons.wikimedia.org/wiki/File:Great_Seal_of_the_United_States_%28obverse_and_reverse%29.png', 0, 'Public domain', 'Wikimedia Commons', 5, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('kant-was-ist-aufklarung-1784', 'Kant, “Beantwortung der Frage: Was ist Aufklärung?” (1784)', 'research', 'Philosophy', 'December 1784', 'Kant’s famous essay defining Enlightenment, published in the Berlinische Monatsschrift.', 'Published the same year as Moses Mendelssohn’s essay on the same question. Both are essential context for understanding what "enlightenment" meant to contemporaries of the Illuminati.', '/assets/img/kant.jpg', 'Portrait of Immanuel Kant', '', '', 0, 'Public domain (text)', 'Berlinische Monatsschrift, December 1784', 6, 'published', 1794301200000, 1794301200000, '{}');
INSERT INTO historical_archives (slug, title, kind, category, date_label, description, body, image, image_alt, file_url, external_url, downloadable, license, source, sort, status, created_at, updated_at, i18n_json) VALUES ('select-bibliography', 'Select bibliography', 'research', 'Research notes', '', 'Scholarly works we rely on for the history of the Bavarian Illuminati.', '- Richard van Dülmen, *Der Geheimbund der Illuminaten. Darstellung, Analyse, Dokumentation* (Stuttgart-Bad Cannstatt: frommann-holzboog, 1975).
