INSERT INTO articles (slug, locale, title, excerpt, body, cover_image, cover_alt, category_id, tags, author_name, status, publish_at, featured, is_announcement, meta_title, meta_description, views, created_at, updated_at, published_at) VALUES ('ingolstadt-1776', 'en', 'Ingolstadt, 1776: how a professor founded a secret society', 'Why would a 28-year-old professor of canon law found a secret society? The answer lies in the university politics of Enlightenment Bavaria.', 'In the spring of 1776 Adam Weishaupt was 28 and already professor of canon law at the University of Ingolstadt. The post had become available because Pope Clement XIV had suppressed the Jesuits three years earlier. It also made Weishaupt enemies among the former Jesuits who remained influential at the university.
INSERT INTO articles (slug, locale, title, excerpt, body, cover_image, cover_alt, category_id, tags, author_name, status, publish_at, featured, is_announcement, meta_title, meta_description, views, created_at, updated_at, published_at) VALUES ('reading-the-sources-critically', 'en', 'Fact, rumour and myth: reading the Illuminati sources critically', 'Almost everything we know about the Illuminati was published by their enemies. Here is how historians deal with that problem.', 'Historians of the Bavarian Illuminati face an unusual problem. Many of the most detailed sources were printed by people who wanted to destroy the order.
INSERT INTO articles (slug, locale, title, excerpt, body, cover_image, cover_alt, category_id, tags, author_name, status, publish_at, featured, is_announcement, meta_title, meta_description, views, created_at, updated_at, published_at) VALUES ('what-did-enlightenment-mean-in-1784', 'en', 'What did “Enlightenment” mean in 1784?', 'In the same year that Bavaria began to move against secret societies, Berlin’s leading journal asked: what is enlightenment?', 'In December 1784 the *Berlinische Monatsschrift* published Immanuel Kant''s answer to a question that had been circulating in its pages: *What is enlightenment?* Moses Mendelssohn had published his own answer in the same journal a few months earlier.
